questionvariables.text:
rlist: [[0,3.4,0.2,1.9,["AF","AD","AC","CD"]],[1,2.9,0.7,2.5,["CD","AD","AC","AF"]],[2,13,5,7,["AF","AD","CD","AC"]],[0,3.1,0.2,1.7,["AF","AC","AD","CD"]],[1,3.1,1.1,1.6,["AD","AF","AC","CD"]],[2,10,5,6,["CD","AC","AF","AD"]],[0,3.8,0.3,1.9,["AF","AC","CD","AD"]],[1,3.1,0.8,2.1,["AD","AC","CD","AF"]],[2,8,3,5,["AD","AC","CD","AF"]],[0,4.1,0.3,2,["AF","AC","CD","AD"]]];
/* Design: angles on a ramp (a prism with right-angled ends): a diagonal and its base. Wheelchair ramps no steeper than 1 in 12; loading ramps 8 to 20 degrees. Part (b) has one named feedback per wrong option. Source: adapted from SMP GCSE Higher 2, Chapter 34, Test yourself T1(c). */
CT: [["A wheelchair ramp at a health centre","m"],["A loading ramp at a cereals depot","m"],["A wooden doorstop","cm"]];
ix: 1+rand(10); RR: rlist[ix];
ctx: CT[RR[1]+1][1]; un: CT[RR[1]+1][2]; aa: RR[2]; rr: RR[3]; bb: RR[4]; OP: RR[5];
LS: "ABCDEF"; LT: [[0,0,0],[aa,0,0],[aa,0,rr],[0,bb,0],[aa,bb,0],[aa,bb,rr]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
r4(v) := float(floor(10000*v+1/2)/10000);
SE: r4(sq("AE")); AE: dst("AE");
th: angd("FAE"); slp: angd("CAB"); wid: float(atan(rr/bb)*180/%pi); cp: 90-th;
thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
opts: makelist([o, is(o = "AC"), o], o, OP);
